import {L,ui,categories,products,projects,roles,people,processSteps,manufactureServices,faqs} from './data.js';
import {company} from './company.js';
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
let lang='ru',route='',category=null,lastFocus=null,gallery=null,toastTimer,visibleProjects=6,visibleLetters=4;
let filters={project:'all',rental:'all',color:'all',search:'',role:'all',language:'all'};
let cart={};try{cart=JSON.parse(sessionStorage.getItem('advex-selection')||'{}');if(!cart||Array.isArray(cart)||typeof cart!=='object')cart={};for(const k of Object.keys(cart))if(!products.some(p=>p.id===k)||!Number.isInteger(cart[k])||cart[k]<1||cart[k]>99)delete cart[k];}catch{cart={};}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=x=>typeof x==='string'?(ui[x]?.[lang]||x):(x?.[lang]||'');
const tr=(r,e,a)=>t(L(r,e,a));
const basePath=new URL('.',import.meta.url).pathname;
const url=(p='',l=lang)=>`${basePath}${l}/${p}`;
const icon=name=>{const paths={plus:'M12 5v14M5 12h14',minus:'M5 12h14',close:'m6 6 12 12M6 18 18 6',menu:'M4 7h16M4 12h16M4 17h16',bag:'M6 8h12l2 12H4L6 8Zm3 0V6a3 3 0 0 1 6 0v2',check:'m5 12 4 4L19 6',filter:'M4 7h16M7 12h10M10 17h4',search:'m16 16 5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',expand:'M8 3H3v5M16 3h5v5M21 16v5h-5M8 21H3v-5',chevron:'m9 5 7 7-7 7',pin:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Zm-5 0a2 2 0 1 1-4 0 2 2 0 0 1 4 0'};return `<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.plus}"/></svg>`;};
const btn=(key,action='form',value='estimate',style='')=>`<button class="btn ${style}" data-action="${action}" data-value="${esc(value)}">${t(key)}</button>`;
const link=(key,p,style='text')=>`<a class="btn ${style}" href="${url(p)}">${t(key)}</a>`;
const photoPath=n=>basePath+'assets/cases/case-'+String(n).padStart(2,'0')+'.jpg';
const casePhoto=(n,alt,loading='lazy')=>`<img class="project-photo real-case-photo" src="${photoPath(n)}" alt="${esc(alt)}" loading="${loading}">`;
const image=(kind,index=0)=>kind==='hero'?casePhoto(14,tr('Стенд Sensemi Azerbaijan из портфолио ADVEX','Sensemi Azerbaijan stand from the ADVEX portfolio','ADVEX portfoliosundan Sensemi Azerbaijan stendi')):`<div role="img" aria-label="${esc(t((kind==='equipment'?products:categories)[index]?.name))}" class="sprite ${kind}" style="--x:${kind==='equipment'?(index%3)*50:(index%4)*100/3}%;--y:${kind==='equipment'?Math.floor(index/3)*100:Math.floor(index/4)*50}%"></div>`;
function section(title,body,{over='',description='',right='',cls='',id=''}={}){return `<section class="section ${cls}" ${id?`id="${id}"`:''}><div class="container">${over?`<div class="overline">${over}</div>`:''}${title?`<div class="section-head"><h2>${title}</h2>${right||(description?`<p>${description}</p>`:'')}</div>`:''}${body}</div></section>`;}
const note=(text=t('demoNotice'))=>`<p class="content-note">${text}</p>`;
function readRoute(){const parts=location.pathname.slice(basePath.length).split('/').filter(Boolean);lang=['ru','en','az'].includes(parts[0])?parts.shift():'ru';route=parts.join('/');category=route.startsWith('stands/')?categories.find(c=>c.id===parts[1]&&parts.length===2):null;const query=new URLSearchParams(location.search);if(route==='projects')filters.project=categories.some(c=>c.id===query.get('type'))?query.get('type'):'all';}
function header(){
 const items=[['manufacturingNav','stands'],['modelsNav','staff'],['shortRental','rental'],['shortProjects','projects'],['about','about'],['contacts','contacts']];
 const catalogActive=route==='catalog'||!!category;
 return `<header class="site-header"><div class="container header-inner"><a class="logo" href="${url()}" aria-label="ADVEX ${t('home')}">advex<span></span></a><nav class="nav" aria-label="${t('menu')}"><div class="nav-stands"><a class="${catalogActive?'active':''}" ${catalogActive?'aria-current="page"':''} href="${url('catalog')}">${t('standsCatalog')}</a><button class="nav-dropdown-toggle" aria-expanded="false" aria-controls="mega" aria-label="${t('openCategories')}" data-action="mega">${icon('chevron')}</button><div class="mega" id="mega" hidden><div class="overline">${t('standsCatalog')}</div><div class="mega-grid">${categories.map(c=>`<a href="${url('stands/'+c.id)}">${t(c.name)}</a>`).join('')}</div></div></div>${items.map(([k,p])=>`<a class="${route===p?'active':''}" ${route===p?'aria-current="page"':''} href="${url(p)}">${t(k)}</a>`).join('')}</nav><div class="language"><select id="language-select" aria-label="${t('siteLanguage')}">${['ru','en','az'].map(l=>`<option value="${l}" ${lang===l?'selected':''}>${l.toUpperCase()}</option>`).join('')}</select></div><button class="cart-toggle" data-action="cart" aria-label="${t('cart')}">${icon('bag')}<span data-cart-count>${countCart()}</span></button><button class="btn dark header-cta" data-action="form" data-value="general">${t('discuss')}</button><button class="menu-toggle" data-action="menu" aria-expanded="false" aria-controls="mobile-menu" aria-label="${t('menu')}">${icon('menu')}</button></div><nav class="mobile-menu" id="mobile-menu" hidden aria-label="${t('menu')}"><a href="${url()}">${t('home')}</a><div class="mobile-catalog-link"><a href="${url('catalog')}">${t('standsCatalog')}</a><button class="nav-dropdown-toggle" data-action="mobile-categories" aria-controls="mobile-categories" aria-expanded="false" aria-label="${t('openCategories')}">${icon('chevron')}</button></div><div id="mobile-categories" hidden>${categories.map(c=>`<a href="${url('stands/'+c.id)}">${t(c.name)}</a>`).join('')}</div>${items.map(([k,p])=>`<a href="${url(p)}">${t(k)}</a>`).join('')}${btn('discuss','form','general')}</nav></header>`;
}
function footer(){return `<footer class="site-footer"><div class="container"><div class="footer-top"><div><a class="logo" href="${url()}">advex<span></span></a><p>${t('heroText')}</p><span class="footer-tag">${t('brandTagline')}</span></div><div><h3>${tr('Направления','What we do','Xidmətlər')}</h3>${['catalog','stands','staff','rental','projects'].map(k=>`<a href="${url(k)}">${k==='catalog'?t('standsCatalog'):t(k)}</a>`).join('')}</div><div><h3>${tr('Конструкции','Structures','Konstruksiyalar')}</h3>${categories.slice(0,4).map(c=>`<a href="${url('stands/'+c.id)}">${t(c.name)}</a>`).join('')}</div><div><h3>ADVEX</h3><div class="footer-contact"><p>${t(company.address)}</p><a href="tel:${company.phones[0].replace(/\s/g,'')}">${company.phones[0]}</a><a href="mailto:${company.email}">${company.email}</a></div>${['about','contacts','delivery','privacy'].map(k=>`<a href="${url(k)}">${t(k)}</a>`).join('')}</div></div><div class="footer-bottom"><span>© 2026 ADVEX · ${tr('Концепция сайта','Website concept','Sayt konsepsiyası')}</span><span>${spokenLanguages(['AZ','EN','RU'])}</span><span>${tr('Выставочные решения в Азербайджане','Exhibition solutions in Azerbaijan','Azərbaycanda sərgi həlləri')}</span></div></div></footer><div class="demo-bar">${t('demoBar')}</div>`;}
function breadcrumbs(title,parent=''){return `<div class="container breadcrumbs"><a href="${url()}">${t('home')}</a><span>/</span>${parent?`<a href="${url('catalog')}">${t('standsCatalog')}</a><span>/</span>`:''}<span aria-current="page">${title}</span></div>`;}
function pageHeading(title,desc='',label='ADVEX',extra=''){return `<section class="page-heading"><div class="container"><div class="overline">${label}</div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}${extra}</div></section>`;}
function hero(title=t('heroTitle'),text=t('heroText'),kind='hero',idx=0){return `<section class="hero"><div class="container hero-grid"><div class="hero-copy"><div class="eyebrow">${t('designProduction')}</div><h1>${title}</h1><p>${text}</p><div class="hero-benefit">${category?.id==='print'?tr('Макет · Печать · Отделка','Artwork · Print · Finishing','Maket · Çap · İşləmə'):t('heroBenefit')}</div><div class="hero-actions">${btn('estimate')}${link('viewProjects',category?'projects?type='+category.id:'projects','outline')}</div><div class="hero-mark">${t('designWord')} <i></i> ${t('buildWord')} <i></i> ${t('impressWord')}</div></div><div class="hero-visual ${kind==='hero'?'':'product-hero'}">${image(kind,idx)}<div class="visual-caption"><span>${t(kind==='hero'?'realProject':'demoProject')}</span><span>01 / ADVEX</span></div></div></div></section>`;}
function spokenLanguages(languages){return languages.map(code=>t({AZ:'languageAz',EN:'languageEn',RU:'languageRu'}[code])).join(' / ');}
function sizeLabel(p){return p.size.replace('cm',tr('см','cm','sm'));}
function portrait(person,extra=''){const index=Number(person.id)-1;return `<div role="img" aria-label="${t('demoPortrait')} ${person.id}" class="model-portrait ${extra}" style="--portrait-x:${(index%3)*50}%;--portrait-y:${Math.floor(index/3)*100}%"></div>`;}
function standCatalog(){return breadcrumbs(t('standsCatalog'))+pageHeading(t('standsCatalog'),t('catalogueIntro'),t('designBuild'))+section('',categoryGrid(),{id:'structures',cls:'catalog-page'})+section(t('catalogueService'),`<div class="request-banner"><p>${t('catalogueServiceText')}</p>${link('manufacturingNav','stands','dark')}</div>`);}
function categoryGrid(items=categories){return `<div class="grid four">${items.map(c=>`<a class="category-card" href="${url('stands/'+c.id)}"><div class="category-image">${image('products',c.index)}</div><div class="category-info"><h3>${t(c.name)}</h3><span class="index">${String(c.index+1).padStart(2,'0')}</span></div></a>`).join('')}</div>`;}
function categorySection(items=categories){return section(t('categoriesTitle'),categoryGrid(items),{over:t('categoriesEyebrow'),description:t('categoriesText'),id:'structures'});}
function projectCards(items,cls=''){return `<div class="project-grid ${cls}">${items.map((p,i)=>`<button class="project-card" data-action="project" data-value="${p.id}"><div class="project-image">${casePhoto(p.photos[0],t(p.name))}<span class="project-label">${t('realProject')}</span><span class="project-open" aria-hidden="true">${icon('plus')}</span></div><div class="project-meta"><div><h3>${t(p.name)}</h3><p>${t(p.type)}</p></div><span class="index">${String(i+1).padStart(2,'0')}</span></div></button>`).join('')}</div>`;}
function projectSection(items=projects.slice(0,4)){return section(t('projectsTitle'),projectCards(items,'featured'),{over:t('selectedConcepts'),right:link('allProjects','projects')});}
function steps(items=processSteps,title=t('process')){return section(title,`<div class="steps">${items.map(([name,desc],i)=>`<div class="step"><span class="step-number">${String(i+1).padStart(2,'0')}</span><h3>${t(name)}</h3><p>${t(desc)}</p></div>`).join('')}</div>`,{over:tr('Порядок работы','Our process','İş prosesi'),cls:'soft'});}
function infoCards(items){return `<div class="grid ${items.length%3===0?'three':'two'} info-grid">${items.map(([name,desc],i)=>`<article class="info-card"><span class="index">${String(i+1).padStart(2,'0')}</span><h3>${t(name)}</h3><p>${t(desc)}</p></article>`).join('')}</div>`;}
function faq(type='stands',cat=null){let list=faqs[type];if(cat)list=[[L(`Для каких задач подходит ${t(cat.name)}?`,`What is ${t(cat.name)} best suited to?`,`${t(cat.name)} hansı tapşırıqlara uyğundur?`),cat.desc],[L('Какие варианты доступны?','Which options are possible?','Hansı variantlar mümkündür?'),cat.variants],[L('Как рассчитывается стоимость?','How is pricing calculated?','Qiymət necə hesablanır?'),L('Цена зависит от размера, тиража, материала и сложности исполнения. Характеристики примера уточняются при обсуждении заказа.','Pricing depends on size, quantity, materials and design complexity. Example specifications are confirmed when discussing the order.','Qiymət ölçü, say, material və icra mürəkkəbliyindən asılıdır. Nümunənin xüsusiyyətləri sifariş müzakirəsində təsdiqlənir.')],faqs.stands[1]];return section(t('faq'),`<div class="faq-layout"><div><p>${tr('Не нашли ответ?<br>Расскажите, что важно для вашего проекта.','Need more detail?<br>Tell us what matters for your project.','Cavab tapa bilmədiniz?<br>Layihəniz üçün vacib olanı bildirin.')}</p>${btn('question','form','general','text')}</div><div class="faq-list">${list.map(([q,a],i)=>`<details><summary><span class="index">0${i+1}</span><span>${t(q)}</span>${icon('plus')}</summary><p>${t(a)}</p></details>`).join('')}</div></div>`,{over:t('faqLabel')});}
function cta(mode='estimate'){return `<section class="cta"><div class="container cta-inner"><div><div class="overline">${t('ctaLabel')}</div><h2>${t('ctaTitle')}</h2><p>${t('ctaText')}</p></div>${btn(mode==='staff'?'pickStaff':'discuss','form',mode,'dark')}</div></section>`;}
function letterImage(i){return `<img src="${basePath}assets/letter-${lang}-${i+1}.svg" alt="${esc(tr('Демонстрационный образец документа','Sample document','Sənəd nümunəsi'))} ${i+1}" loading="lazy">`;}
function letters(expanded=false){const count=expanded?visibleLetters:4;return section(t('reviews'),`${note(t('reviewsNote'))}<div class="grid four letters">${Array.from({length:count},(_,i)=>`<button class="letter-card" data-action="letter" data-value="${i}">${letterImage(i)}<span>${tr('Образец документа','Sample document','Sənəd nümunəsi')} ${String(i+1).padStart(2,'0')}</span></button>`).join('')}</div>${expanded&&count<8?`<div class="center-action">${btn('showMore','more-letters','','outline')}</div>`:''}`,{over:tr('Доверие в деталях','Trust in the details','Etibar detallardadır'),cls:'soft',id:'letters'});}
function clients(){return section(t('clients'),`<div class="client-placeholders">${['01','02','03','04','05'].map(n=>`<div><span>${tr('Партнёр','Partner','Tərəfdaş')} ${n}</span><small>${tr('Место для логотипа','Logo placeholder','Loqo üçün yer')}</small></div>`).join('')}</div>${note(t('clientsNote'))}`);}
function benefits(){return section(tr('Один проект.<br>Всё внимание к деталям.','One project.<br>Every detail considered.','Bir layihə.<br>Hər detala diqqət.'),infoCards([[L('Единая концепция','A single vision','Vahid konsepsiya'),L('Стенд, графика и оборудование в одном визуальном решении.','Stand, graphics and equipment in one visual direction.','Stend, qrafika və avadanlıq vahid vizual həll daxilində.')],[L('Понятный состав работ','A clear scope','Aydın iş həcmi'),L('Задачи, этапы и бюджет согласовываются до изготовления.','Scope, stages and budget are agreed before production.','Tapşırıqlar, mərhələlər və büdcə istehsaldan əvvəl razılaşdırılır.')],[L('Внимание к площадке','Venue-aware design','Məkanın nəzərə alınması'),L('Планировка и логистика учитывают формат мероприятия.','Layout and logistics take the event format into account.','Plan və logistika tədbirin formatını nəzərə alır.')]]),{over:tr('Предлагаемый подход','Proposed approach','Təklif olunan yanaşma')});}
function categoryCostFactors(c){if(c.id==='print')return [L('Формат и страницы','Format & pages','Format və səhifələr'),L('Тираж','Print quantity','Tiraj'),L('Бумага','Paper','Kağız'),L('Цветность','Printing colours','Çap rəngləri'),L('Отделка','Finishing','İşləmə'),L('Сроки','Schedule','Müddət')];return [L('Размеры','Dimensions','Ölçülər'),L('Количество','Quantity','Say'),L('Материалы','Materials','Materiallar'),L('Графика и отделка','Graphics & finishing','Qrafika və işləmə'),c.id==='signs'?L('Подсветка и крепление','Lighting & mounting','İşıqlandırma və bərkitmə'):L('Сложность исполнения','Design complexity','İcra mürəkkəbliyi'),L('Сроки изготовления','Production schedule','İstehsal müddəti')];}
function costSection(){return section(t('cost'),`<div class="cost-grid">${(category?categoryCostFactors(category):[L('Площадь и планировка','Area & layout','Sahə və plan'),L('Сложность конструкции','Structural complexity','Konstruksiya mürəkkəbliyi'),L('Материалы и отделка','Materials & finishes','Materiallar və üzlük'),L('Свет и мультимедиа','Lighting & multimedia','İşıq və multimedia'),L('Оборудование','Equipment','Avadanlıq'),L('Сроки и монтаж','Schedule & installation','Müddət və quraşdırma')]).map((x,i)=>`<div><span class="index">0${i+1}</span><h3>${t(x)}</h3></div>`).join('')}</div><div class="cost-footer"><p>${tr('Каждая задача индивидуальна. Подтверждённые тарифы отсутствуют — стоимость по запросу.','Every brief is different. Approved rates are not yet available — pricing is on request.','Hər tapşırıq fərdidir. Təsdiqlənmiş tarif yoxdur — qiymət sorğu əsasında verilir.')}</p>${btn('estimate')}</div>`,{cls:'dark'});}
function productCard(p){return `<article class="product-card"><button class="product-image" data-action="product" data-value="${p.id}" aria-label="${t('more')}: ${esc(t(p.name))}">${image('equipment',p.index)}</button><div class="product-info"><span class="overline">${t(p.cat)}</span><button class="product-title" data-action="product" data-value="${p.id}"><h3>${t(p.name)}</h3></button><p>${sizeLabel(p)}</p><div class="product-bottom"><span>${t('request')}</span><button class="add-button" data-action="add" data-value="${p.id}" aria-label="${t('add')}: ${esc(t(p.name))}">${icon('plus')}</button></div></div></article>`;}
function rentalPreview(){return section(tr('Детали, которые<br>дополняют пространство.','Details that<br>complete the space.','Məkanı tamamlayan<br>detallar.'),`<div class="grid three">${products.slice(0,3).map(productCard).join('')}</div>`,{over:t('rental'),right:link('catalog','rental')});}
function turnkey(){return section('',`<div class="split-feature"><div class="split-image">${image('hero')}<span class="image-disclaimer">${t('realProject')}</span></div><div class="split-copy"><div class="overline">${t('designBuild')}</div><h2>${tr('От чистого листа<br>до готового стенда.','From a blank page<br>to a finished stand.','Boş vərəqdən<br>hazır stendə.')}</h2><p>${tr('Объединяем проектирование, визуальную концепцию и организацию производства в последовательный процесс.','We bring planning, visual design and production coordination into one connected process.','Layihələndirmə, vizual konsepsiya və istehsalın təşkilini vahid prosesdə birləşdiririk.')}</p><div class="service-tags">${[L('Проектирование','Planning','Layihələndirmə'),L('Дизайн','Design','Dizayn'),L('Изготовление','Production','İstehsal'),L('Доставка','Delivery','Çatdırılma'),L('Монтаж','Installation','Quraşdırma'),L('Демонтаж','Dismantling','Sökülmə')].map(x=>`<span>${t(x)}</span>`).join('')}</div>${link('more','stands')}</div></div>`);}
function aboutPreview(){return section('',`<div class="about-statement"><div><div class="overline">${t('aboutLabel')}</div><h2>${tr('Создаём место<br>для больших идей.','Making room<br>for bigger ideas.','Böyük ideyalara<br>məkan yaradırıq.')}</h2></div><div><p>${t(company.intro)}</p>${link('about','about','outline')}</div></div>`,{cls:'dark'});}
function home(){return hero()+`<div class="service-strip"><div class="container">${['stands','staff','rental'].map((k,i)=>`<a href="${url(k)}"><span class="index">0${i+1}</span>${t(k)}</a>`).join('')}</div></div>`+categorySection()+section(tr('Всё для вашего<br>участия в выставке.','Everything for your<br>exhibition presence.','Sərgidə iştirakınız<br>üçün hər şey.'),`<div class="service-cards"><a class="service-feature" href="${url('stands')}">${image('hero')}<div><span class="index">01 / ${t('designBuild')}</span><h3>${t('stands')}</h3><p>${tr('Пространства, созданные вокруг вашего бренда.','Spaces built around your brand.','Brendiniz ətrafında qurulmuş məkanlar.')}</p><span class="service-more">${t('more')}</span></div></a><div class="service-secondary"><a href="${url('staff')}"><span class="index">02 / ${t('shortStaff')}</span><h3>${t('staff')}</h3><p>${tr('Люди, с которых начинается знакомство.','People who make the first connection.','İlk ünsiyyəti quran insanlar.')}</p><span class="service-more">${t('more')}</span></a><a href="${url('rental')}"><span class="index">03 / ${t('equipmentLabel')}</span><h3>${t('rental')}</h3><p>${tr('Мебель и техника для комфортной работы.','Furniture and technology for a productive event.','Rahat iş üçün mebel və texnika.')}</p><span class="service-more">${t('more')}</span></a></div></div>`,{cls:'soft',over:tr('Три направления. Одна команда.','Three directions. One team.','Üç istiqamət. Bir komanda.')})+projectSection()+turnkey()+steps()+rentalPreview()+aboutPreview()+clients()+letters()+faq()+formSection('general');}
function standsPage(){return breadcrumbs(t('stands'))+hero(tr('Стенды под ключ.<br><em>Ваша идея —<br>в масштабе.</em>','Turnkey stands.<br><em>Your vision,<br>at scale.</em>','Açar təslimi stendlər.<br><em>İdeyanız —<br>böyük miqyasda.</em>'))+categorySection()+section(tr('Каждая часть<br>на своём месте.','Every part<br>in its place.','Hər hissə<br>öz yerində.'),infoCards(manufactureServices),{over:tr('Состав услуги','Our services','Xidmətin tərkibi')})+projectSection()+steps()+section(tr('Материалы, форма<br>и технология.','Materials, form<br>and technology.','Material, forma<br>və texnologiya.'),infoCards([[L('Каркас','Structure','Karkas'),L('Конструкция подбирается под площадь, нагрузки и регламент площадки.','The structure is selected for the area, loads and venue rules.','Konstruksiya sahə, yük və məkan qaydalarına uyğun seçilir.')],[L('Графическое оформление','Graphic design','Qrafik tərtibat'),L('Печать, текстиль и вывески рассматриваются в составе общей концепции.','Print, textiles and signage are considered as part of the overall concept.','Çap, tekstil və lövhələr ümumi konsepsiya daxilində nəzərdən keçirilir.')],[L('Свет и оснащение','Lighting & equipment','İşıq və avadanlıq'),L('Сценарии освещения и размещение оборудования уточняются по задаче.','Lighting and equipment layouts are defined by your requirements.','İşıq ssenariləri və avadanlığın yeri tapşırığa əsasən dəqiqləşdirilir.')]])+note(tr('Предлагаемые варианты. Материалы и технологии требуют подтверждения ADVEX.','Proposed options. Materials and technologies require confirmation by ADVEX.','Təklif olunan variantlar. Material və texnologiyalar ADVEX tərəfindən təsdiqlənməlidir.')))+costSection()+benefits()+letters()+faq()+formSection('estimate');}
function categoryPage(c){const related=projects.filter(p=>p.cats.includes(c.id));return breadcrumbs(t(c.name),'stands')+hero(`${t(c.name)}.<br><em>${tr('Ваш бренд<br>в центре внимания.','Your brand<br>in focus.','Brendiniz<br>diqqət mərkəzində.')}</em>`,t(c.desc),'products',c.index)+section(tr('Конструкция под вашу задачу','Built around your brief','Tapşırığınıza uyğun konstruksiya'),`<div class="category-detail"><p class="large-copy">${t(c.desc)}</p><dl><div><dt>${t('specs')}</dt><dd>${t(c.spec)}</dd></div><div><dt>${t('variants')}</dt><dd>${t(c.variants)}</dd></div><div><dt>${t('cost')}</dt><dd>${t('request')}</dd></div></dl></div>${note(tr('Размеры и варианты приведены как примеры, ассортимент уточняется.','Sizes and options are illustrative; the range requires confirmation.','Ölçü və variantlar nümunədir, çeşid dəqiqləşdiriləcək.'))}`)+section(tr('Почему этот формат','Why this format','Niyə bu format'),infoCards([[c.name,c.desc],[L('Варианты для вашего бренда','Options for your brand','Brendiniz üçün variantlar'),c.variants]]),{cls:'soft'})+section(tr('Примеры этого формата','Examples of this format','Bu formatın nümunələri'),related.length?projectCards(related):`<div class="empty-state"><h3>${tr('Примеры готовятся','Examples are being prepared','Nümunələr hazırlanır')}</h3><p>${tr('Расскажите о задаче — обсудим подходящее исполнение.','Tell us your goals so we can discuss a suitable design.','Tapşırığınızı bildirin — uyğun həlli müzakirə edək.')}</p>${btn('discuss')}</div>`,{right:link('allProjects','projects?type='+c.id)})+costSection()+faq('stands',c)+formSection('estimate')+section(tr('Другие решения','Other solutions','Digər həllər'),categoryGrid(categories.filter(x=>x.id!==c.id).slice(0,4)));}
function portfolio(){return breadcrumbs(t('projects'))+pageHeading(t('projects'),t('projectsIntro'),t('portfolioLabel'))+section('',`<div class="filter-row project-filters" aria-label="${t('filters')}">${filterChips('project',categories.map(c=>[c.id,t(c.name)]))}</div><div id="project-results">${portfolioResults()}</div>`,{id:'project-gallery'})+letters()+cta();}
function filterChips(type,items){return [['all',t('all')],...items].map(([value,label])=>`<button class="chip ${filters[type]===value?'selected':''}" data-action="filter" data-filter="${type}" data-value="${value}" aria-pressed="${filters[type]===value}">${label}</button>`).join('');}
function empty(){return `<div class="empty-state"><div class="empty-icon">${icon('search')}</div><h3>${t('empty')}</h3><p>${t('emptyHelp')}</p>${btn('reset','reset','','outline')}</div>`;}
function portfolioResults(){const items=projects.filter(p=>filters.project==='all'||p.cats.includes(filters.project));return `<div class="result-line"><span role="status">${t('found')}: ${items.length}</span>${filters.project!=='all'?btn('reset','reset','','text'):''}</div>${items.length?projectCards(items.slice(0,visibleProjects)):empty()}${items.length>visibleProjects?`<div class="center-action">${btn('showMore','more-projects','','outline')}</div>`:''}`;}
function rental(){return breadcrumbs(t('rental'))+pageHeading(tr('Аренда оборудования.<br><em>Всё для вашего стенда.</em>','Equipment rental.<br><em>Made for your stand.</em>','Avadanlıq icarəsi.<br><em>Stendiniz üçün hər şey.</em>'),tr('Мебель, витрины и мультимедиа. Соберите свой список — стоимость и доступность уточняются по запросу.','Furniture, display cabinets and multimedia. Build your selection — prices and availability are confirmed on request.','Mebel, vitrinlər və multimedia. Siyahınızı hazırlayın — qiymət və mövcudluq sorğu əsasında dəqiqləşdirilir.'),t('rental'),`<a class="btn dark" href="#rental-catalog">${tr('Выбрать оборудование','Choose equipment','Avadanlıq seçin')}</a>`)+section('',`<div class="rental-category-grid">${products.map(p=>`<button class="rental-category ${filters.rental===p.id?'selected':''}" data-action="filter" data-filter="rental" data-value="${p.id}">${image('equipment',p.index)}<span>${t(p.cat)}</span></button>`).join('')}</div><div class="catalog-layout"><aside class="catalog-filters">${rentalFilters()}</aside><div class="catalog-main"><div class="catalog-toolbar"><label class="search-box">${icon('search')}<input id="equipment-search" type="search" placeholder="${t('search')}" aria-label="${t('search')}" value="${esc(filters.search)}"></label><button class="btn outline mobile-filter" data-action="mobile-filters">${icon('filter')}${t('filters')}</button><button class="btn dark selection-button" data-action="cart">${icon('bag')}${t('cart')} <span data-cart-count>${countCart()}</span></button></div><div id="rental-results">${rentalResults()}</div></div></div>${note(tr('Демонстрационный ассортимент. Изображения созданы для прототипа, характеристики и доступность требуют подтверждения.','Illustrative range. Images were created for the prototype; specifications and availability require confirmation.','Nümayiş çeşidi. Şəkillər prototip üçün yaradılıb; xüsusiyyət və mövcudluq təsdiqlənməlidir.'))}`,{id:'rental-catalog'})+section(tr('Аренда по понятному плану','A clear rental process','Aydın icarə prosesi'),infoCards([[L('Выберите оборудование','Select equipment','Avadanlıq seçin'),L('Добавьте позиции и количество в единый список.','Add items and quantities to one selection.','Avadanlıq və sayını vahid siyahıya əlavə edin.')],[L('Уточните условия','Agree the terms','Şərtləri dəqiqləşdirin'),L('Период, адрес, доставка и монтаж обсуждаются индивидуально.','Dates, address, delivery and setup are discussed individually.','Müddət, ünvan, çatdırılma və quraşdırma fərdi müzakirə olunur.')],[L('Согласуйте возврат','Arrange the return','Qaytarılmanı razılaşdırın'),L('Порядок возврата фиксируется до начала аренды.','The return procedure is agreed before the rental starts.','Qaytarılma qaydası icarə başlamazdan əvvəl razılaşdırılır.')]])+link('delivery','delivery'),{cls:'soft'})+benefits()+letters()+faq('rental')+section(tr('Ваш список готов?','Selection ready?','Siyahınız hazırdır?'),`<div class="request-banner"><p>${t('rentalNote')}</p>${btn('cart','cart')}</div>`);}
function rentalFilters(){return `<h3>${t('filters')}</h3><fieldset><legend>${tr('Категория','Category','Kateqoriya')}</legend>${[['all',t('all')],...products.map(p=>[p.id,t(p.cat)])].map(([v,label])=>`<label class="radio-row"><input type="radio" name="rental-category" value="${v}" data-filter-input="rental" ${filters.rental===v?'checked':''}><span>${label}</span></label>`).join('')}</fieldset><label class="field-label">${t('color')}<select data-filter-input="color"><option value="all">${t('all')}</option>${['white','black','gray'].map(c=>`<option value="${c}" ${filters.color===c?'selected':''}>${t(c)}</option>`).join('')}</select></label>${btn('reset','reset','','text')}`;}
function rentalResults(){const list=products.filter(p=>(filters.rental==='all'||p.id===filters.rental)&&(filters.color==='all'||p.color===filters.color)&&`${t(p.name)} ${t(p.cat)}`.toLocaleLowerCase().includes(filters.search.toLocaleLowerCase().trim()));return `<div class="result-line" role="status">${t('found')}: ${list.length}</div>${list.length?`<div class="grid three products-grid">${list.map(productCard).join('')}</div>`:empty()}`;}
function roleTask(i){return [L('Встреча и сопровождение гостей','Welcoming and guiding guests','Qonaqların qarşılanması və müşayiəti'),L('Презентация продукции и промоакции','Product presentations and promotions','Məhsul təqdimatı və promosiyalar'),L('Работа на стенде и ответы на вопросы','Stand support and visitor enquiries','Stenddə iş və sualların cavablandırılması'),L('Регистрация участников и навигация','Attendee registration and wayfinding','İştirakçı qeydiyyatı və istiqamətləndirmə'),L('Языковое сопровождение встреч','Language support for meetings','Görüşlərdə dil dəstəyi')][i];}
function staffResults(){const list=people.filter(p=>(filters.role==='all'||p.role===Number(filters.role))&&(filters.language==='all'||p.langs.includes(filters.language)));return `<div class="result-line" role="status">${t('found')}: ${list.length}</div>${list.length?`<div class="grid three">${list.map(p=>`<button class="person-card" data-action="person" data-value="${p.id}"><div class="person-visual">${portrait(p)}<span class="person-demo">${t('demoProfileLabel')}</span></div><div class="person-info"><h3>${tr('Анкета','Profile','Profil')} ${p.id}</h3><div class="profile-role">${t(roles[p.role])}</div><p>${spokenLanguages(p.langs)}</p><span class="service-more">${t('profile')}</span></div></button>`).join('')}</div>`:empty()}`;}
function staffPage(){return breadcrumbs(t('staff'))+`<section class="staff-hero"><div class="container staff-intro"><div><div class="overline">${t('peopleLabel')}</div><h1>${tr('Персонал на выставку.<br><em>Люди вашего бренда.</em>','Exhibition staff.<br><em>The people behind your brand.</em>','Sərgi heyəti.<br><em>Brendinizin nümayəndələri.</em>')}</h1><p>${tr('Встречать, рассказывать, помогать. Подбор выставочного персонала под задачи вашего мероприятия.','Welcome, present, support. Exhibition staffing shaped around your event.','Qarşılamaq, təqdim etmək, kömək etmək. Tədbirinizin tapşırıqlarına uyğun sərgi heyəti.')}</p>${btn('pickStaff','form','staff','dark')}</div><div class="staff-poster"><span>${t('meet')}<br>${t('connect')}<br><em>${t('inspire')}</em></span><div>${spokenLanguages(['AZ','EN','RU'])}<br>${tr('Языки вашего события','The languages of your event','Tədbirinizin dilləri')}</div></div></div></section>`+section(tr('Правильные люди.<br>Для каждой задачи.','The right people.<br>For every role.','Hər tapşırıq üçün<br>doğru insanlar.'),`<div class="role-grid">${roles.map((r,i)=>`<button class="role-card" data-action="role-jump" data-value="${i}"><span class="index">0${i+1}</span><h3>${t(r)}</h3><p>${t(roleTask(i))}</p></button>`).join('')}</div>`)+section(tr('Примеры анкет','Example profiles','Profil nümunələri'),`${note(tr('Фотографии созданы с помощью ИИ. Анкеты вымышленные и показывают сценарий подбора персонала.','AI-generated portraits and fictional profiles illustrate the staff selection process.','Süni intellektlə yaradılmış portretlər və uydurma profillər heyət seçimini nümayiş etdirir.'))}<div class="staff-filters"><label>${t('role')}<select data-filter-input="role"><option value="all">${t('all')}</option>${roles.map((r,i)=>`<option value="${i}" ${filters.role===String(i)?'selected':''}>${t(r)}</option>`).join('')}</select></label><label>${t('languages')}<select data-filter-input="language"><option value="all">${t('all')}</option>${['AZ','EN','RU'].map(l=>`<option value="${l}" ${filters.language===l?'selected':''}>${spokenLanguages([l])}</option>`).join('')}</select></label>${btn('reset','reset','','text')}</div><div id="staff-results">${staffResults()}</div>`,{id:'staff-catalog',cls:'soft'})+steps([L('Заявка','Request','Sorğu'),L('Требования','Requirements','Tələblər'),L('Подбор','Selection','Seçim'),L('Согласование','Approval','Razılaşdırma'),L('Подготовка','Preparation','Hazırlıq'),L('Мероприятие','The event','Tədbir')].map((x,i)=>[x,[L('Дата, место и задачи','Dates, venue and duties','Tarix, məkan və tapşırıqlar'),L('Роли, языки и график','Roles, languages and schedule','Rollar, dillər və qrafik'),L('Кандидатуры по задаче','Candidates for your brief','Tapşırığa uyğun namizədlər'),L('Подтверждение состава','Team confirmation','Heyətin təsdiqi'),L('Инструктаж по мероприятию','Event briefing','Tədbir üzrə təlimat'),L('Работа по согласованному плану','Work to the agreed plan','Razılaşdırılmış plan üzrə iş')][i]]),tr('От задачи — к команде.','From your brief to your team.','Tapşırıqdan komandaya.'))+section(tr('Где работает команда','Where the team works','Komanda harada işləyir'),`<div class="event-example"><div>${image('hero')}</div><div><span class="overline">${t('demo')}</span><h3>${tr('Выставки и деловые события','Exhibitions and business events','Sərgilər və işgüzar tədbirlər')}</h3><p>${tr('Встреча гостей, регистрация, презентация продукции и информационная поддержка. На фото — стенд из портфолио ADVEX; анкеты персонала в прототипе демонстрационные.','Guest welcome, registration, product presentations and information support. The photo shows a stand from the ADVEX portfolio; staff profiles in this prototype are illustrative.','Qonaqların qarşılanması, qeydiyyat, məhsul təqdimatı və məlumat dəstəyi. Fotoda ADVEX portfoliosundan stend göstərilib; prototipdəki heyət profilləri nümunədir.')}</p></div></div>`)+benefits()+faq('staff')+formSection('staff');}
function about(){return breadcrumbs(t('about'))+pageHeading(tr('О компании ADVEX.<br><em>От проекта к выставке.</em>','About ADVEX.<br><em>From design to exhibition.</em>','ADVEX haqqında.<br><em>Layihədən sərgiyə.</em>'),t(company.intro),t('aboutLabel'))+section('',`<div class="about-wide-image">${casePhoto(14,tr('Стенд из портфолио ADVEX','Stand from the ADVEX portfolio','ADVEX portfoliosundan stend'))}<span class="image-disclaimer">${t('realProject')}</span></div>`)+section(tr('Работаем в Азербайджане<br>с 2022 года.','Working in Azerbaijan<br>since 2022.','2022-ci ildən<br>Azərbaycanda fəaliyyət göstəririk.'),`<div class="narrative-columns"><p>${t(company.history)}</p><p>${t(company.association)} ${t(company.priorities)}</p></div>`)+section('',`<div class="stats"><div><strong>2022</strong><h3>${tr('Основание компании','Company registration','Şirkətin qeydiyyatı')}</h3><p>${tr('20 мая','20 May','20 may')}</p></div><div><strong>2023</strong><h3>${tr('Вступление в АСТА','Joined ASTA','ASTA üzvlüyü')}</h3><p>${tr('Ассоциация организаторов выставок Азербайджана','Azerbaijan Exhibition Organisers Association','Azərbaycan Sərgi Təşkilatçıları Assosiasiyası')}</p></div><div><strong>${tr('Баку','Baku','Bakı')}</strong><h3>${tr('Офис ADVEX','ADVEX office','ADVEX ofisi')}</h3><p>${t(company.address)}</p></div></div>`,{cls:'soft'})+section(tr('От технического задания<br>до готового стенда.','From your brief<br>to the finished stand.','Texniki tapşırıqdan<br>hazır stendə.'),infoCards([[L('Дизайн-проект','Stand design','Stend layihəsi'),L('Разрабатываем проект по техническому заданию заказчика.','We develop the design from the client’s brief.','Layihəni sifarişçinin texniki tapşırığına əsasən hazırlayırıq.')],[L('Монтаж и демонтаж','Installation and dismantling','Quraşdırma və sökülmə'),L('Собираем стенд в выставочном павильоне по утверждённому проекту и демонтируем после события.','We assemble the approved design at the exhibition venue and dismantle it after the event.','Təsdiqlənmiş layihəni sərgi pavilyonunda quraşdırır, tədbirdən sonra sökürük.')],[L('Мебель и оборудование','Furniture and equipment','Mebel və avadanlıq'),L('Предоставляем оснащение в аренду на время выставки.','We rent furnishings and equipment for the duration of the exhibition.','Sərgi müddətində mebel və avadanlığı icarəyə veririk.')]]))+projectSection()+letters(true)+cta('general');}
function delivery(){return breadcrumbs(t('delivery'))+pageHeading(tr('Доставка и оплата.<br><em>Всё по плану.</em>','Delivery & payment.<br><em>Everything to plan.</em>','Çatdırılma və ödəniş.<br><em>Hər şey plana uyğun.</em>'),tr('Логистика, монтаж и документы — часть подготовки вашего участия. Окончательные условия фиксируются в предложении.','Logistics, installation and documents are part of preparing your participation. Final terms are set out in the proposal.','Logistika, quraşdırma və sənədlər iştirak hazırlığının bir hissəsidir. Yekun şərtlər təklifdə qeyd olunur.'),t('delivery'))+section(tr('Способы доставки','Delivery options','Çatdırılma üsulları'),infoCards([[L('На площадку','To the venue','Tədbir məkanına'),L('Адрес, пропуска и требования к разгрузке уточняются до расчёта.','Address, access passes and unloading requirements are clarified before quoting.','Ünvan, giriş icazələri və boşaltma tələbləri hesablanmadan əvvəl dəqiqləşdirilir.')],[L('Крупные конструкции','Large structures','Böyük konstruksiyalar'),L('Маршрут, габариты и способ перевозки планируются по составу заказа.','Route, dimensions and transport are planned around your order.','Marşrut, ölçülər və daşıma üsulu sifarişə əsasən planlaşdırılır.')],[L('После мероприятия','After the event','Tədbirdən sonra'),L('Демонтаж и возврат аренды согласовываются заранее.','Dismantling and rental returns are arranged in advance.','Sökülmə və icarənin qaytarılması əvvəlcədən razılaşdırılır.')]]))+steps([L('Заказ','Order','Sifariş'),L('Сроки','Schedule','Müddət'),L('Подготовка','Preparation','Hazırlıq'),L('Доставка','Delivery','Çatdırılma'),L('Установка','Installation','Quraşdırma'),L('Возврат','Return','Qaytarılma')].map((x,i)=>[x,[L('Согласование состава','Confirm the scope','İş həcminin razılaşdırılması'),L('Подтверждение графика','Confirm the schedule','Qrafikin təsdiqi'),L('Комплектация заказа','Prepare the order','Sifarişin hazırlanması'),L('Доступ на площадку','Venue access','Məkana giriş'),L('Сборка и проверка','Assembly and inspection','Yığım və yoxlama'),L('Согласованный демонтаж','Agreed dismantling','Razılaşdırılmış sökülmə')][i]]),tr('Как проходит доставка','How delivery works','Çatdırılma necə aparılır'))+section(tr('Монтаж и демонтаж','Installation & dismantling','Quraşdırma və sökülmə'),`<div class="narrative-columns"><p>${tr('Нужны план площадки, правила организатора, доступное время монтажа и технические требования. Это позволяет подготовить последовательность работ.','A floor plan, organiser rules, installation access times and technical requirements are needed to plan the work.','İşləri planlaşdırmaq üçün məkan planı, təşkilatçı qaydaları, quraşdırma vaxtı və texniki tələblər lazımdır.')}</p><p>${tr('Время демонтажа и вывоз оборудования согласовываются вместе с графиком мероприятия. Сроки подтверждаются при согласовании заказа.','Dismantling and collection are agreed with the event schedule. Timing is confirmed when the order is agreed.','Sökülmə və avadanlığın daşınması tədbir qrafiki ilə razılaşdırılır. Müddət sifariş razılaşdırılarkən təsdiqlənir.')}</p></div>`)+section(tr('Сроки и условия','Timing & terms','Müddət və şərtlər'),`<div class="terms-table">${[[L('География','Coverage','Ərazi'),L('Подтверждается по адресу мероприятия','Confirmed for the event address','Tədbir ünvanına görə təsdiqlənir')],[L('Стоимость доставки','Delivery cost','Çatdırılma qiyməti'),L('По объёму, габаритам и маршруту','Based on volume, dimensions and route','Həcm, ölçü və marşruta görə')],[L('Возврат оборудования','Equipment return','Avadanlığın qaytarılması'),L('По согласованному графику и перечню','According to the agreed schedule and inventory','Razılaşdırılmış qrafik və siyahı üzrə')]].map(([a,b])=>`<div><h3>${t(a)}</h3><p>${t(b)}</p></div>`).join('')}</div>`,{cls:'soft'})+section(tr('Оплата и документы','Payment & documents','Ödəniş və sənədlər'),infoCards([[L('Способы оплаты','Payment methods','Ödəniş üsulları'),L('Подтверждённые способы и валюта будут добавлены после согласования. Язык интерфейса не определяет валюту.','Approved methods and currency will be added after confirmation. Interface language does not determine currency.','Təsdiqlənmiş üsullar və valyuta razılaşdırıldıqdan sonra əlavə ediləcək. İnterfeys dili valyutanı müəyyən etmir.')],[L('Оформление документов','Documentation','Sənədləşmə'),L('Состав договора, счёта и закрывающих документов уточняется индивидуально.','Contract, invoice and completion documentation are agreed individually.','Müqavilə, hesab və yekun sənədlər fərdi razılaşdırılır.')]]))+faq('delivery')+cta('general');}
function privacy(){const parts=[
 [L('Статус документа','Document status','Sənədin statusu'),L('Это структура будущей политики конфиденциальности, а не утверждённый юридический документ. Текст должен быть предоставлен и согласован ADVEX на каждом языке.','This is the structure for a future privacy policy, not an approved legal document. ADVEX must supply and approve the text in each language.','Bu, gələcək məxfilik siyasətinin strukturudur, təsdiqlənmiş hüquqi sənəd deyil. Mətn hər dildə ADVEX tərəfindən təqdim və təsdiq edilməlidir.')],
 [L('Данные в прототипе','Data in the prototype','Prototipdə məlumatlar'),L('Введённые в формы данные проверяются в браузере. Реальная отправка заявок, загрузка вложений и серверное хранение не выполняются. Не вводите конфиденциальные сведения для тестирования.','Form details are validated in the browser. Requests are not actually submitted, attachments are not uploaded and data is not stored on a server. Do not enter confidential information for testing.','Forma məlumatları brauzerdə yoxlanılır. Sorğular real göndərilmir, fayllar yüklənmir və məlumatlar serverdə saxlanılmır. Sınaq üçün məxfi məlumat daxil etməyin.')],
 [L('Сессионное хранение','Session storage','Sessiya yaddaşı'),L('Список оборудования и количества сохраняются в сессионном хранилище текущего браузера для переходов между страницами. Контактные данные и содержимое форм в это хранилище не записываются.','Equipment identifiers and quantities are saved in browser sessionStorage for navigation between pages. Contact details and form contents are not written to that storage.','Avadanlıq identifikatorları və sayları səhifələr arası keçid üçün brauzerin sessiya yaddaşında saxlanılır. Əlaqə və forma məlumatları ora yazılmır.')],
 [L('Будущий рабочий сайт','Future live website','Gələcək işlək sayt'),L('До запуска необходимо определить оператора данных, цели и основания обработки, сроки хранения, получателей, права пользователей и порядок обращений. Эти положения требуют отдельной юридической подготовки.','Before launch, the data controller, processing purposes and grounds, retention periods, recipients, user rights and enquiry process must be specified. These provisions require separate legal preparation.','İşə salınmadan əvvəl məlumat operatoru, emal məqsədləri və əsasları, saxlanma müddəti, alıcılar, istifadəçi hüquqları və müraciət qaydası müəyyən edilməlidir. Bu müddəalar ayrıca hüquqi hazırlıq tələb edir.')],
 [L('Контакты оператора','Controller contact details','Operatorun əlaqə məlumatları'),L('Юридическое наименование, адрес и ответственный за обработку данных будут указаны после предоставления подтверждённых реквизитов компании.','The legal name, address and responsible contact will be added once verified company details are supplied.','Hüquqi ad, ünvan və məlumat emalına cavabdeh şəxsin əlaqəsi şirkətin təsdiqlənmiş rekvizitləri təqdim edildikdən sonra əlavə olunacaq.')]
 ];return breadcrumbs(t('privacy'))+pageHeading(t('privacy'),tr('Черновая структура · версия прототипа от 9 октября 2026','Draft structure · prototype version, 9 October 2026','Qaralama struktur · prototip versiyası, 9 oktyabr 2026'),t('legalLabel'))+section('',`<div class="legal-layout"><aside><h3>${tr('Содержание','Contents','Mündəricat')}</h3>${parts.map(([h],i)=>`<a href="#policy-${i}">${i+1}. ${t(h)}</a>`).join('')}</aside><article class="legal-text">${parts.map(([h,p],i)=>`<section id="policy-${i}"><h2>${i+1}. ${t(h)}</h2><p>${t(p)}</p></section>`).join('')}<a class="btn outline" href="${url('contacts')}">${t('contacts')}</a></article></div>`);}
function contacts(){return breadcrumbs(t('contacts'))+pageHeading(tr('Контакты.<br><em>Начнём с вашей идеи.</em>','Contact.<br><em>It starts with your idea.</em>','Əlaqə.<br><em>İdeyanızdan başlayaq.</em>'),tr('Расскажите о своей выставке, идее или задаче.','Tell us about your exhibition, idea or project.','Sərginiz, ideyanız və ya tapşırığınız barədə danışın.'),t('contactLabel'))+section('',`<div class="contact-layout"><div><h2>ADVEX</h2><div class="contact-list"><div><span>${t('address')}</span><p>${t(company.address)}</p></div><div><span>${t('phone')}</span><p class="contact-phones">${company.phones.map(number=>`<a href="tel:${number.replace(/\s/g,'')}">${number}</a>`).join('')}</p></div><div><span>${t('email')}</span><p><a href="mailto:${company.email}">${company.email}</a></p></div></div><a class="btn dark" href="${company.directions}" target="_blank" rel="noopener">${tr('Открыть на карте','Open in maps','Xəritədə aç')}</a></div><div class="contact-form"><h2>${tr('Написать нам','Send an enquiry','Bizə yazın')}</h2>${form('general')}</div></div>`)+section('',`<div class="office-map"><div class="map-heading"><div><div class="overline">${tr('Наш офис','Our office','Ofisimiz')}</div><h2>${tr('Встретимся в Баку','Meet us in Baku','Bakıda görüşək')}</h2><p>${t(company.address)}</p></div><a class="btn outline" href="${company.directions}" target="_blank" rel="noopener">${tr('Построить маршрут','Get directions','Marşrut qur')}</a></div><iframe title="${tr('Офис ADVEX на карте','ADVEX office map','ADVEX ofisinin xəritəsi')}" src="${company.map}&hl=${lang}" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe></div>`)+section(t('legal'),`<div class="legal-placeholder"><p><strong>${company.name}</strong><br>${tr('Дата регистрации: 20 мая 2022 года.','Registration date: 20 May 2022.','Qeydiyyat tarixi: 20 may 2022.')}</p><p>${tr('Налоговые и банковские реквизиты уточняйте у компании.','Please contact us for tax and bank details.','Vergi və bank rekvizitləri üçün bizimlə əlaqə saxlayın.')}</p>${link('privacy','privacy')}</div>`,{cls:'soft'});}
function formSection(mode){return section(mode==='staff'?t('pickStaff'):mode==='general'?t('discuss'):t('estimate'),`<div class="form-section"><div><p class="large-copy">${t('ctaText')}</p><p>${t('required')}</p><p class="content-note">${t('demoBar')}</p></div><div>${form(mode,category?t(category.name):'')}</div></div>`,{cls:'soft',id:'request-form'});}
function field(name,label,{type='text',required=false,full=false,value='',min='',options=null}={}){return `<label class="field ${full?'full':''}"><span>${label}${required?' *':''}</span>${options?`<select name="${name}" ${required?'required':''}>${options}</select>`:type==='textarea'?`<textarea name="${name}" rows="4" ${required?'required':''}>${esc(value)}</textarea>`:`<input name="${name}" type="${type}" ${required?'required':''} ${min?`min="${min}"`:''} value="${esc(value)}" ${name==='contact'?'autocomplete="email"':name==='name'?'autocomplete="name"':name==='company'?'autocomplete="organization"':''} ${type==='number'?'step="1"':''}>`}</label>`;}
function form(mode,context=''){const common=field('name',t('name'),{required:true})+field('company',t('company'))+field('contact',t('contact'),{required:true,full:true});let extra='';if(mode==='estimate')extra=field('event',t('event'))+field('area',t('area'),{type:'number',min:'1'})+field('date',t('date'),{type:'date'})+field('type',tr('Тип конструкции','Structure type','Konstruksiya növü'),{value:context||(category?t(category.name):'')});if(mode==='staff')extra=field('date',t('date'),{type:'date',required:true})+field('location',t('location'),{required:true})+field('staffCount',t('staffCount'),{type:'number',min:'1',required:true,value:'1'})+field('role',t('role'),{options:roles.map((r,i)=>`<option value="${i}" ${filters.role===String(i)?'selected':''}>${t(r)}</option>`).join('')})+field('languages',t('languages'),{full:true,value:filters.language==='all'?'':spokenLanguages([filters.language])});if(mode==='rental')extra=field('start',t('start'),{type:'date',required:true})+field('end',t('end'),{type:'date',required:true})+field('location',t('location'),{full:true,required:true});if(mode==='general')extra=field('subject',t('subject'),{full:true,value:context});return `<form class="request-form" data-mode="${mode}" novalidate><div class="form-grid">${common}${extra}${field('details',t('details'),{type:'textarea',full:true,value:mode==='staff'?context:''})}${mode==='estimate'?`<label class="field full upload-field"><span>${t('file')}</span><span class="upload-control"><input type="file" name="file" accept=".pdf,.jpg,.jpeg,.png,.docx" aria-label="${tr('Выбрать файл','Choose file','Fayl seç')}"><span class="upload-button">${tr('Выбрать файл','Choose file','Fayl seç')}</span><span class="upload-filename" aria-live="polite">${tr('Файл не выбран','No file selected','Fayl seçilməyib')}</span></span><small>${t('fileHint')}</small></label>`:''}</div><label class="consent"><input type="checkbox" name="consent" required><span>${t('consent')} <a href="${url('privacy')}" target="_blank" rel="noopener">${t('privacyLink')}</a>. *</span></label><div class="form-error" role="alert" hidden></div><button class="btn dark submit-button" type="submit">${t('send')}</button><p class="form-note">${tr('Демонстрация: данные не отправляются.','Demo: no data will be sent.','Nümayiş: məlumatlar göndərilmir.')}</p><details class="test-mode"><summary>${t('testMode')}</summary><label><select name="testMode" aria-label="${t('testMode')}"><option value="success">${t('testSuccess')}</option><option value="error">${t('testError')}</option></select></label></details></form>`;}
function metadata(){let title=category?t(category.name):route==='catalog'?t('standsCatalog'):route?t(route):tr('Выставочные стенды и пространства','Exhibition stands and spaces','Sərgi stendləri və məkanlar');if(!['','catalog','stands','staff','rental','projects','about','contacts','delivery','privacy'].includes(route)&&!category)title=t('unknown');document.title=`${title} — ADVEX`;document.documentElement.lang=lang;document.querySelector('meta[name="description"]').content=category?t(category.desc):`${title}. ${t('heroText')} ${tr('Интерактивный прототип.','Interactive prototype.','İnteraktiv prototip.')}`;document.querySelectorAll('link[hreflang]').forEach(e=>e.remove());for(const l of ['az','en','ru']){const el=document.createElement('link');el.rel='alternate';el.hreflang=l;el.href=location.origin+url(route,l);document.head.append(el);}document.querySelector('.skip').textContent=tr('К содержимому','Skip to content','Məzmuna keç');}
function render({scroll=true}={}){readRoute();if(modal.open)modal.close();const pages={'':home,catalog:standCatalog,stands:standsPage,projects:portfolio,rental,staff:staffPage,about,delivery,privacy,contacts};const body=category?categoryPage(category):(Object.hasOwn(pages,route)?pages[route]():pageHeading(t('unknown'),'','404',link('backHome','','dark')));app.innerHTML=header()+`<main id="main" tabindex="-1">${body}</main>`+footer();metadata();if(scroll)window.scrollTo(0,0);}
function navigate(href){const dest=new URL(href,location.origin);if(dest.pathname===location.pathname&&dest.search===location.search&&dest.hash){document.getElementById(decodeURIComponent(dest.hash.slice(1)))?.scrollIntoView();return;}history.pushState({},'',dest.pathname+dest.search+dest.hash);render();if(dest.hash)document.getElementById(decodeURIComponent(dest.hash.slice(1)))?.scrollIntoView();document.querySelector('main')?.focus({preventScroll:true});}
function showModal(content,cls=''){if(!modal.open)lastFocus=document.activeElement;const preserveFullscreen=gallery&&modal.classList.contains('fullscreen');modal.className=cls+(preserveFullscreen?' fullscreen':'');modal.innerHTML=`<button class="modal-close" data-action="close" aria-label="${t('close')}">${icon('close')}</button>${content}`;if(!modal.open)modal.showModal();document.body.classList.add('modal-open');modal.scrollTop=0;}
function closeModal(){modal.close();}
modal.addEventListener('close',()=>{document.body.classList.remove('modal-open');gallery=null;if(lastFocus?.isConnected)lastFocus.focus({preventScroll:true});});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
function showForm(mode='estimate',context=''){gallery=null;showModal(`<div class="modal-body"><div class="overline">${t('ctaLabel')}</div><h2 id="modal-title">${t(mode==='estimate'?'estimate':mode==='staff'?'pickStaff':'discuss')}</h2>${context?`<p class="context-label">${esc(context)}</p>`:''}${form(mode,context)}</div>`);}
function projectModal(id){if(!projects.some(x=>x.id===id))return;gallery={type:'project',id,index:0,zoom:false};drawGallery();}
function letterModal(index){gallery={type:'letter',index:Number(index),zoom:false};drawGallery();}
function drawGallery(){if(!gallery)return;const g=gallery,p=projects.find(x=>x.id===g.id);if(g.type==='letter'){showModal(`<div class="modal-body"><div class="overline">${t('demo')}</div><h2 id="modal-title">${tr('Образец документа','Sample document','Sənəd nümunəsi')} ${g.index+1}</h2><p class="content-note">${t('reviewsNote')}</p><div class="gallery-toolbar"><button class="icon-btn" data-action="gallery-prev" aria-label="${t('prev')}"><span class="rotate">${icon('chevron')}</span></button><span>${g.index+1} / 8</span><button class="icon-btn" data-action="gallery-next" aria-label="${t('next')}">${icon('chevron')}</button><button class="btn outline" data-action="zoom">${t(g.zoom?'zoomOut':'zoom')}</button><button class="icon-btn" data-action="fullscreen" aria-label="${t('fullscreen')}">${icon('expand')}</button></div><div class="document-view ${g.zoom?'zoomed':''}">${letterImage(g.index)}</div></div>`,'document-modal');return;}const views=p.photos;showModal(`<div class="gallery-media ${g.zoom?'zoomed':''}">${casePhoto(views[g.index],t(p.name)+' · '+(g.index+1),'eager')}</div><div class="modal-body"><div class="gallery-toolbar"><button class="icon-btn" data-action="gallery-prev" aria-label="${t('prev')}"><span class="rotate">${icon('chevron')}</span></button><span>${g.index+1} / ${views.length}</span><button class="icon-btn" data-action="gallery-next" aria-label="${t('next')}">${icon('chevron')}</button><button class="icon-btn" data-action="zoom" aria-label="${t(g.zoom?'zoomOut':'zoom')}">${icon(g.zoom?'minus':'plus')}</button><button class="icon-btn" data-action="fullscreen" aria-label="${t('fullscreen')}">${icon('expand')}</button></div><div class="overline">${t('realProject')}</div><h2 id="modal-title">${t(p.name)}</h2><p>${t(p.type)}</p><p class="content-note">${tr('Фотографии из портфолио ADVEX.','Photos from the ADVEX portfolio.','ADVEX portfoliosundan fotolar.')} <a class="source-link" href="${company.sources.gallery}" target="_blank" rel="noopener">${tr('Посмотреть источник','View source','Mənbəyə bax')}</a></p><div class="service-tags">${p.cats.map(id=>`<a href="${url('stands/'+id)}">${t(categories.find(c=>c.id===id).name)}</a>`).join('')}</div><button class="btn dark" data-action="similar" data-value="${p.id}">${t('similar')}</button></div>`,'project-modal');}
function productModal(id){const p=products.find(x=>x.id===id);if(!p)return;gallery=null;showModal(`<div class="product-modal-grid"><div class="product-modal-image">${image('equipment',p.index)}</div><div class="modal-body"><div class="overline">${t(p.cat)}</div><h2 id="modal-title">${t(p.name)}</h2><p>${t(p.desc)}</p><dl class="product-specs"><div><dt>${t('size')}</dt><dd>${sizeLabel(p)}</dd></div><div><dt>${t('color')}</dt><dd>${t(p.color)}</dd></div><div><dt>${t('cost')}</dt><dd>${t('request')}</dd></div></dl>${note(t('demo'))}<label class="field">${t('quantity')}<input type="number" id="product-quantity" value="1" min="1" max="99" step="1"></label><button class="btn dark" data-action="add-detail" data-value="${p.id}">${t('add')}</button></div></div>`,'wide-modal');}
function personModal(id){const p=people.find(x=>x.id===id);gallery=null;showModal(`<div class="modal-body"><div class="overline">${t('demoProfile')}</div><h2 id="modal-title">${tr('Анкета','Profile','Profil')} ${p.id}</h2><div class="profile-details">${portrait(p,'profile-portrait')}<div><h3>${t(roles[p.role])}</h3><p>${t(roleTask(p.role))}</p><p>${t('languages')}: <strong>${spokenLanguages(p.langs)}</strong></p><p>${tr('График и стоимость — по запросу.','Schedule and pricing on request.','Qrafik və qiymət sorğu əsasında.')}</p></div></div>${note(tr('Пример структуры анкеты, без персональных данных и реального бронирования.','Example profile structure, without personal data or real booking.','Şəxsi məlumat və real bron olmadan profil strukturu nümunəsi.'))}<button class="btn dark" data-action="choose-person" data-value="${p.id}">${t('pickStaff')}</button></div>`);}
function countCart(){return Object.values(cart).reduce((a,b)=>a+b,0);}
function saveCart(){try{sessionStorage.setItem('advex-selection',JSON.stringify(cart));}catch{}document.querySelectorAll('[data-cart-count]').forEach(e=>e.textContent=countCart());}
function addCart(id,qty=1){if(!products.some(p=>p.id===id)||!Number.isInteger(qty)||qty<1||qty>99)return;cart[id]=Math.min(99,(cart[id]||0)+qty);saveCart();toast(t('added'));}
function cartRows(){return products.filter(p=>cart[p.id]).map(p=>`<div class="cart-row"><div class="cart-image">${image('equipment',p.index)}</div><div class="cart-description"><h3>${t(p.name)}</h3><p>${t('request')}</p><button class="remove-link" data-action="remove" data-value="${p.id}" aria-label="${t('remove')}: ${t(p.name)}">${t('remove')}</button></div><div class="quantity-control"><button data-action="decrease" data-value="${p.id}" aria-label="${tr('Уменьшить количество','Decrease quantity','Sayı azalt')}: ${t(p.name)}" ${cart[p.id]===1?'disabled':''}>${icon('minus')}</button><input type="number" min="1" max="99" step="1" value="${cart[p.id]}" data-cart-quantity="${p.id}" aria-label="${t('quantity')}: ${t(p.name)}"><button data-action="increase" data-value="${p.id}" aria-label="${tr('Увеличить количество','Increase quantity','Sayı artır')}: ${t(p.name)}" ${cart[p.id]===99?'disabled':''}>${icon('plus')}</button></div></div>`).join('');}
function cartModal(){gallery=null;showModal(`<div class="modal-body"><div class="overline">${t('cart')}</div><h2 id="modal-title">${t('cart')}</h2>${countCart()?`<div class="cart-items">${cartRows()}</div><p class="content-note">${t('rentalNote')}</p>${btn('send','rental-form','','dark')}`:`<div class="empty-state">${icon('bag')}<h3>${t('emptyCart')}</h3><p>${t('emptyCartHelp')}</p>${link('catalog','rental','dark')}</div>`}</div>`,'cart-modal');}
function rentalForm(){if(!countCart()){cartModal();return;}showModal(`<div class="modal-body"><div class="overline">${t('rental')}</div><h2 id="modal-title">${t('send')}</h2><div class="rental-summary">${products.filter(p=>cart[p.id]).map(p=>`<div><span>${t(p.name)}</span><strong>× ${cart[p.id]}</strong></div>`).join('')}</div><button class="btn text" data-action="cart">${tr('Изменить список','Edit selection','Siyahını dəyiş')}</button><p class="content-note">${t('rentalNote')}</p>${form('rental')}</div>`);}
function toast(message){const e=document.querySelector('#toast');e.textContent=message;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),2800);}
function updateFilters(){if(route==='rental'){document.querySelector('#rental-results').innerHTML=rentalResults();document.querySelectorAll('[data-filter-input="rental"]').forEach(el=>el.checked=el.value===filters.rental);document.querySelectorAll('[data-filter-input="color"]').forEach(el=>el.value=filters.color);document.querySelectorAll('.rental-category').forEach(el=>el.classList.toggle('selected',el.dataset.value===filters.rental));}if(route==='projects'){document.querySelector('#project-results').innerHTML=portfolioResults();document.querySelectorAll('.project-filters .chip').forEach(el=>{el.classList.toggle('selected',el.dataset.value===filters.project);el.setAttribute('aria-pressed',el.dataset.value===filters.project);});history.replaceState({},'',url('projects')+(filters.project==='all'?'':'?type='+filters.project));}if(route==='staff'){document.querySelector('#staff-results').innerHTML=staffResults();document.querySelectorAll('[data-filter-input]').forEach(el=>el.value=filters[el.dataset.filterInput]);}}
document.addEventListener('click',e=>{const a=e.target.closest('a');if(a&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&!e.altKey&&a.target!=='_blank'&&a.origin===location.origin){e.preventDefault();if(modal.open)closeModal();navigate(a.href);return;}const target=e.target.closest('[data-action]');if(!target)return;const action=target.dataset.action,value=target.dataset.value;
 if(action==='form')showForm(value||'estimate');
 if(action==='close')closeModal();
 if(action==='mobile-categories'){const list=document.querySelector('#mobile-categories');list.hidden=!list.hidden;target.setAttribute('aria-expanded',!list.hidden);}
 if(action==='menu'){const nav=document.querySelector('#mobile-menu');nav.hidden=!nav.hidden;target.setAttribute('aria-expanded',!nav.hidden);}
 if(action==='mega'){const nav=document.querySelector('#mega');nav.hidden=!nav.hidden;target.setAttribute('aria-expanded',!nav.hidden);}
 if(action==='project')projectModal(value);
 if(action==='letter')letterModal(value);
 if(action==='product')productModal(value);
 if(action==='person')personModal(value);
 if(action==='similar'){const p=projects.find(p=>p.id===value);showForm('estimate',t(p.name));}
 if(action==='choose-person'){const p=people.find(x=>x.id===value);filters.role=String(p.role);showForm('staff',`${tr('Пример анкеты','Example profile','Profil nümunəsi')} ${p.id}: ${t(roles[p.role])}, ${spokenLanguages(p.langs)}`);}
 if(action==='role-jump'){filters.role=value;updateFilters();document.querySelector('#staff-catalog').scrollIntoView();}
 if(action==='add')addCart(value);
 if(action==='add-detail'){const input=document.querySelector('#product-quantity');if(input.reportValidity())addCart(value,Number(input.value));}
 if(action==='cart')cartModal();
 if(action==='rental-form')rentalForm();
 if(['remove','increase','decrease'].includes(action)){if(action==='remove')delete cart[value];else cart[value]=Math.max(1,Math.min(99,cart[value]+(action==='increase'?1:-1)));saveCart();cartModal();}
 if(action==='filter'){filters[target.dataset.filter]=value;visibleProjects=6;updateFilters();}
 if(action==='reset'){filters={project:'all',rental:'all',color:'all',search:'',role:'all',language:'all'};const search=document.querySelector('#equipment-search');if(search)search.value='';updateFilters();}
 if(action==='more-projects'){visibleProjects+=6;updateFilters();}
 if(action==='more-letters'){const y=window.scrollY;visibleLetters=8;render({scroll:false});window.scrollTo(0,y);}
 if(action==='mobile-filters')showModal(`<div class="modal-body"><h2 id="modal-title">${t('filters')}</h2>${rentalFilters()}${btn('apply','close','','dark')}</div>`,'filter-modal');
 if(action==='gallery-next'||action==='gallery-prev'){if(gallery){const max=gallery.type==='letter'?8:projects.find(p=>p.id===gallery.id).photos.length;gallery.index=(gallery.index+(action==='gallery-next'?1:-1)+max)%max;gallery.zoom=false;drawGallery();}}
 if(action==='zoom'&&gallery){gallery.zoom=!gallery.zoom;drawGallery();}
 if(action==='fullscreen')modal.classList.toggle('fullscreen');
 if(action==='map-in'||action==='map-out'){const map=document.querySelector('.demo-map');const zoom=Math.max(1,Math.min(2.5,Number(map.dataset.zoom||1)+(action==='map-in'?.25:-.25)));map.dataset.zoom=zoom;map.style.setProperty('--map-scale',zoom);map.querySelector('.map-scale').textContent=Math.round(zoom*100)+'%';}
});
document.addEventListener('keydown',e=>{
 if(modal.open&&e.key==='Tab'){
  const controls=[...modal.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),summary,[tabindex="0"]')].filter(el=>el.getClientRects().length && el.checkVisibility() && (!el.closest('details:not([open])') || el.tagName==='SUMMARY'));
  const first=controls[0],last=controls.at(-1);
  if(e.shiftKey&&(document.activeElement===first||!modal.contains(document.activeElement))){e.preventDefault();last?.focus();}
  else if(!e.shiftKey&&(document.activeElement===last||!modal.contains(document.activeElement))){e.preventDefault();first?.focus();}
 }
 if(modal.open&&gallery&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)){if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();modal.querySelector(`[data-action="gallery-${e.key==='ArrowRight'?'next':'prev'}"]`)?.click();}}
 if(e.key==='Escape'){document.querySelector('#mobile-menu')?.setAttribute('hidden','');document.querySelector('.menu-toggle')?.setAttribute('aria-expanded','false');document.querySelector('#mega')?.setAttribute('hidden','');document.querySelector('.nav-dropdown-toggle')?.setAttribute('aria-expanded','false');}
});
document.addEventListener('input',e=>{if(e.target.id==='equipment-search'){filters.search=e.target.value;updateFilters();}if(e.target.closest('.request-form')){e.target.setCustomValidity?.('');e.target.removeAttribute('aria-invalid');}});
document.addEventListener('change',e=>{const el=e.target;if(el.matches('input[type="file"]')){el.closest('.upload-control').querySelector('.upload-filename').textContent=el.files[0]?.name||tr('Файл не выбран','No file selected','Fayl seçilməyib');}if(el.id==='language-select'){navigate(url(route,el.value)+location.search+location.hash);return;}if(el.dataset.filterInput){filters[el.dataset.filterInput]=el.value;updateFilters();}if(el.dataset.cartQuantity){const val=Number(el.value);if(Number.isInteger(val)&&val>=1&&val<=99){cart[el.dataset.cartQuantity]=val;saveCart();}else el.value=cart[el.dataset.cartQuantity];}});
document.addEventListener('submit',async e=>{const f=e.target.closest('.request-form');if(!f)return;e.preventDefault();if(f.dataset.busy)return;const error=f.querySelector('.form-error');error.hidden=true;f.querySelectorAll('input,select,textarea').forEach(el=>{el.setCustomValidity('');el.removeAttribute('aria-invalid');});const data=new FormData(f),contact=String(data.get('contact')||'').trim();let message='';f.querySelectorAll('[required]').forEach(el=>{if(el.type!=='checkbox'&&typeof el.value==='string'&&!el.value.trim())el.setCustomValidity(t('validation'));});const invalid=[...f.elements].find(el=>el.willValidate&&!el.checkValidity());if(invalid)message=t('validation');if(!message&&!(/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(contact)||(/^[+\d\s().-]+$/.test(contact)&&contact.replace(/\D/g,'').length>=7))){message=t('badContact');f.elements.contact.setCustomValidity(message);}if(!message&&f.dataset.mode==='rental'&&data.get('end')<data.get('start')){message=t('badDates');f.elements.end.setCustomValidity(message);}const file=data.get('file');if(!message&&file?.size&&(file.size>10*1024*1024||!/\.(pdf|jpe?g|png|docx)$/i.test(file.name))){message=t('badFile');f.elements.file.setCustomValidity(message);}if(!message&&f.dataset.mode==='rental'&&!countCart())message=t('emptyCart');if(message){error.textContent=message;error.hidden=false;const bad=[...f.elements].find(el=>el.willValidate&&!el.checkValidity());bad?.setAttribute('aria-invalid','true');bad?.focus();return;}const submit=f.querySelector('.submit-button');const submittingLang=lang;f.dataset.busy='true';submit.disabled=true;submit.textContent=t('sending');await new Promise(resolve=>setTimeout(resolve,650));if(!f.isConnected||lang!==submittingLang)return;delete f.dataset.busy;if(data.get('testMode')==='error'){error.textContent=t('error');error.hidden=false;submit.disabled=false;submit.textContent=t('send');return;}f.innerHTML=`<div class="form-success" role="status" tabindex="-1"><span>${icon('check')}</span><h3>${t('success')}</h3><p>${t('successText')}</p>${modal.contains(f)?btn('close','close','','dark'):btn('discuss','form','general','dark')}</div>`;f.querySelector('.form-success').focus();});
window.addEventListener('popstate',()=>render());
render();
// Progressive enhancement: shares the exact state and actions of the visible UI.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'stage_rental_selection',title:'Add equipment to a demo request',description:'Stage equipment and quantities in the visible local demo selection. Does not book equipment or submit a request.',inputSchema:{type:'object',properties:{items:{type:'array',items:{type:'object',properties:{id:{type:'string',enum:products.map(p=>p.id)},quantity:{type:'integer',minimum:1,maximum:99}},required:['id','quantity'],additionalProperties:false},minItems:1}},required:['items'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!Array.isArray(input.items)||!input.items.length||input.items.some(x=>!products.some(p=>p.id===x.id)||!Number.isInteger(x.quantity)||x.quantity<1||x.quantity>99))throw new Error('Invalid equipment selection');for(const x of input.items)addCart(x.id,x.quantity);cartModal();return {selection:{...cart},submitted:false};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}





